import { execFileSync } from "node:child_process";
import {
	existsSync,
	mkdtempSync,
	readdirSync,
	rmSync,
	writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";

import {
	type FauxResponseStep,
	fauxAssistantMessage,
	fauxThinking,
	fauxToolCall,
} from "@earendil-works/pi-ai/providers/faux";
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

import { withReplyReminder } from "./context.ts";
import type { ActionInputs } from "./inputs.ts";
import { pushThread } from "./push.ts";
import { type ActionDependencies, type Logger, run } from "./run.ts";
import {
	createActionInputs,
	createComment,
	createLogger,
	createMockGitHubClient,
	fauxModels,
	git,
	tempDir,
	tempRemote,
} from "./test-helpers.ts";
import type { GitHubComment, GitHubReaction } from "./types.ts";

const REF = "refs/pi/threads/42";
/** Where a run keeps REF locally (liveRef()). */
const LIVE = "refs/pi-action/threads/42";
const FIRST_COMMIT = /pi-durable: seq 1 /u;
const COMMIT_ID = /^[0-9a-f]{40}$/u;
const CONTINUE = "Your last response hit the output token limit (max_tokens)";

/** The info lines and groups `log` gets, in order (`::group::<name>`, `::endgroup::`). */
function logLines(log: Logger): string[] {
	const lines: string[] = [];
	vi.mocked(log.info).mockImplementation((line) => {
		lines.push(line);
	});
	vi.mocked(log.startGroup).mockImplementation((name) => {
		lines.push(`::group::${name}`);
	});
	vi.mocked(log.endGroup).mockImplementation(() => {
		lines.push("::endgroup::");
	});
	return lines;
}

/** A bare "GitHub" remote, a fresh runner checkout per run, a faux model, and a fake GitHub API. */
function world() {
	const { remote, clone } = tempRemote();
	const { faux, models, model } = fauxModels();
	const comments: GitHubComment[] = [];
	const gh = createMockGitHubClient(comments);
	let nextId = 100;
	const comment = (body: string, overrides: Partial<GitHubComment> = {}) => {
		nextId += 1;
		const c = createComment({
			id: nextId,
			body,
			created_at: new Date().toISOString(),
			html_url: `https://github.com/o/r/issues/42#issuecomment-${nextId}`,
			...overrides,
		});
		comments.push(c);
		return c;
	};
	/** The comment IDs that got `reaction`. */
	const reacted = (reaction: GitHubReaction) =>
		vi
			.mocked(gh.addReaction)
			.mock.calls.filter(([, r]) => r === reaction)
			.map(([target]) => target.commentId);
	const deps = (
		trigger: GitHubComment | undefined,
		inputs: Partial<ActionInputs> = {},
		payload?: Record<string, unknown>,
	): ActionDependencies => ({
		inputs: createActionInputs({
			provider: model.provider,
			model: model.id,
			timeout: 30,
			pollInterval: 0.05,
			...inputs,
		}),
		payload: payload ?? {
			comment: trigger,
			issue: {
				number: 42,
				title: "Fix the thing",
				body: "It is broken",
				user: { login: "o", type: "User" },
			},
		},
		createClient: () => gh,
		log: createLogger(),
		cwd: clone("--depth", "1"),
		createModels: async () => models,
		summary: vi.fn(async (_markdown: string) => undefined),
		env: {
			GITHUB_REPOSITORY: "o/r",
			GITHUB_RUN_ID: "777",
			GITHUB_RUN_ATTEMPT: "1",
			GITHUB_ACTOR: "dispatcher",
		},
	});
	return { remote, faux, gh, comment, deps, reacted };
}

const userTexts = (messages: { role: string; content: unknown }[]) =>
	messages
		.filter((m) => m.role === "user")
		.map((m) =>
			typeof m.content === "string"
				? m.content
				: (m.content as { type: string; text?: string }[])
						.map((b) => b.text ?? "")
						.join(""),
		);

/** The text of the last tool result the model saw. */
const toolText = (messages: { role: string; content: unknown }[]): string => {
	const result = messages.findLast((m) => m.role === "toolResult");
	return Array.isArray(result?.content)
		? (result.content as { text?: string }[]).map((b) => b.text ?? "").join("")
		: "";
};

/** Git as on a runner: no global or system config, so no identity. */
function runnerGitEnv(): Record<string, string> {
	const home = tempDir();
	const global = join(home, "gitconfig");
	writeFileSync(global, "");
	return { HOME: home, GIT_CONFIG_GLOBAL: global, GIT_CONFIG_NOSYSTEM: "1" };
}

describe("run (durable)", () => {
	it("ignores edited comments that are not answers to questions", async () => {
		const w = world();
		const trigger = w.comment("@pi fix it");
		const deps = w.deps(
			undefined,
			{},
			{
				action: "edited",
				comment: trigger,
				issue: {
					number: 42,
					title: "Fix the thing",
					body: "It is broken",
					user: { login: "o", type: "User" },
				},
			},
		);
		await run(deps);
		expect(deps.log.info).toHaveBeenCalledWith(
			"An edited comment that is not an answer to a question; skipping",
		);
		expect(w.gh.addReaction).not.toHaveBeenCalled();
		expect(w.gh.posted).toHaveLength(0);
	});

	it("gives the agent's tools GH_TOKEN and a git identity when the runner has none", async () => {
		const w = world();
		w.faux.setResponses([
			fauxAssistantMessage(
				[
					fauxToolCall("bash", {
						command:
							'printf "%s|%s|%s" "$GH_TOKEN" "$GIT_AUTHOR_NAME" "$GIT_COMMITTER_EMAIL"',
					}),
				],
				{ stopReason: "toolUse" },
			),
			(context) =>
				fauxAssistantMessage(`Tool said: ${toolText(context.messages)}`),
		]);
		const deps = w.deps(w.comment("@pi who am I?"));
		deps.env = { ...deps.env, ...runnerGitEnv() };

		await run(deps);

		expect(w.gh.posted[0]).toContain(
			"Tool said: test-token|github-actions[bot]|41898282+github-actions[bot]@users.noreply.github.com",
		);
		expect(deps.log.info).toHaveBeenCalledWith(
			"The agent's tools get GH_TOKEN, GIT_AUTHOR_NAME, GIT_AUTHOR_EMAIL, GIT_COMMITTER_NAME, GIT_COMMITTER_EMAIL",
		);
		// Without pi-durable extensions, the action's own environment is left alone.
		expect(deps.env).not.toHaveProperty("GH_TOKEN");
	});

	it("leaves the checkout's git hooks alone, so pi commits in the repository's own format", async () => {
		const w = world();
		const message = "release: v0.35.1";
		w.faux.setResponses([
			fauxAssistantMessage(
				[
					fauxToolCall("bash", {
						command: `git commit -q --allow-empty -m "${message}" && git log -1 --format=%B`,
					}),
				],
				{ stopReason: "toolUse" },
			),
			(context) =>
				fauxAssistantMessage(`Committed: ${toolText(context.messages)}`),
		]);
		const deps = w.deps(w.comment("@pi cut the release"));
		// A repository whose hooks live in the working tree (husky, lefthook, a committed .githooks/).
		git(deps.cwd, "config", "core.hooksPath", ".githooks");
		const hooksDirectory = join(deps.cwd, ".git", "hooks");
		const hooksBefore = readdirSync(hooksDirectory).toSorted();

		await run(deps);

		expect(readdirSync(hooksDirectory).toSorted()).toStrictEqual(hooksBefore);
		expect(
			hooksBefore.filter((name) => !name.endsWith(".sample")),
		).toStrictEqual([]);
		expect(existsSync(join(deps.cwd, ".githooks"))).toBe(false);
		expect(git(deps.cwd, "status", "--porcelain")).toBe("");
		expect(git(deps.cwd, "log", "-1", "--format=%B").trim()).toBe(message);
		expect(w.gh.posted[0]).toContain(`Committed: ${message}`);
	});

	it("answers a trigger, posts once, and pushes the thread to the remote", async () => {
		const w = world();
		w.faux.setResponses([fauxAssistantMessage("Fixed it.")]);
		const trigger = w.comment("@pi please fix");

		await run(w.deps(trigger));

		expect(w.gh.posted).toHaveLength(1);
		expect(w.gh.posted[0]).toContain("### 🤖 pi Response\n\nFixed it.");
		expect(w.gh.posted[0]).toContain(REF);
		expect(w.reacted("eyes")).toStrictEqual([trigger.id]);
		expect(w.reacted("rocket")).toStrictEqual([trigger.id]);
		const log = git(w.remote, "log", "--format=%s", REF);
		expect(log).toMatch(FIRST_COMMIT);
	});

	it("logs the thread first, then what pi does, the reply, and where the thread ends up", async () => {
		const w = world();
		w.faux.setResponses([
			fauxAssistantMessage(
				[
					{ type: "text", text: "Looking." },
					fauxToolCall("bash", { command: "echo hi" }),
				],
				{ stopReason: "toolUse" },
			),
			fauxAssistantMessage("Fixed it."),
		]);
		const trigger = w.comment("@pi please fix\nthe thing");
		const author = trigger.user?.login;
		const deps = w.deps(trigger);
		const lines = logLines(deps.log);

		await run(deps);

		const tip = git(w.remote, "rev-parse", REF).trim();
		expect(tip).toBe(git(deps.cwd, "rev-parse", LIVE).trim());
		const setupEnd = lines.indexOf("::endgroup::");
		expect(lines[0]).toBe("::group::Setup");
		expect(lines.slice(setupEnd + 1)).toStrictEqual([
			expect.stringMatching(/^🤖 faux\S*\/\S+$/u),
			`::group::🧵 Thread ${REF}: new`,
			expect.stringContaining(
				`This conversation is stored in git on ${REF}. To read it:\n  git fetch origin '${REF}:${REF}'\n`,
			),
			"::endgroup::",
			`▶ Request from @${String(author)} (${trigger.html_url}): please fix the thing`,
			"💬 Looking.",
			"🔧 bash: echo hi",
			expect.stringMatching(/^::group:: {2}↳ ✓ \d+\.\ds · 1 line$/u),
			"command: echo hi",
			"──",
			"hi",
			"::endgroup::",
			"💬 Fixed it.",
			expect.stringMatching(
				/^✅ Replied: https:\/\/\S+ \(2 model responses · 1 tool call · \d+\.\ds · \S+ tokens in, \S+ out\)$/u,
			),
			`🧵 ${REF} is at ${tip.slice(0, 7)}`,
		]);
		// The plumbing is debug output.
		expect(deps.log.debug).toHaveBeenCalledWith(`${REF}: new on origin`);
		expect(deps.summary).toHaveBeenCalledExactlyOnceWith(
			expect.stringContaining(`git log --oneline ${REF}`),
		);
	});

